from zipfile import ZipFile
p='/mnt/data/GMRI_Public_Research_AUTHOR_REVIEW_2026-10-28.zip'
refs=['knowledge_system/reports/CORRECTED_COUNTS_AND_METHOD.md','knowledge_system/docs/10_STATUS_AND_EVIDENCE_MAPPING.md','knowledge_system/docs/09_EXTERNAL_REVIEW_RESPONSE.md','knowledge_system/docs/04_THREAT_MODEL_ALIGNMENT.md']
with ZipFile(p) as z:
 for name in refs:
  t=next((n for n in z.namelist() if n.endswith(name)),None)
  print('\n====== '+name+' ======')
  s=z.read(t).decode('utf-8','replace');
  if name.endswith('04_THREAT_MODEL_ALIGNMENT.md'):
   for line in s.splitlines():
    if line.startswith('| H') or line.startswith('##') or line.startswith('#') or 'coupled' in line.lower(): print(line)
  else: print(s[:6500])
PY

