bash -lc cat > /mnt/data/gev_av_work/mission.test.mjs <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { brierScore, classifyAdmission, cueAt, formatTime, chapterDelta } from './mission-core.mjs';

test('Brier is 0.0784 for an illustrative 72 percent forecast of yes', () => {
  assert.equal(brierScore(0.72, 1), 0.0784);
});

test('unresolved outcomes produce no Brier score rather than zero', () => {
  assert.equal(brierScore(0.72, null), null);
});

test('Brier refuses out of range probabilities', () => {
  assert.throws(() => brierScore(1.2, 1), RangeError);
});

test('forecast gate stops for stale, look-ahead, circular, provisional-only evidence', () => {
  assert.deepEqual(classifyAdmission({stale:true,lookahead:true,circular:true,provisional:true}).reasons,
    ['STALE SOURCE','LOOK-AHEAD','CIRCULAR SUPPORT','ONLY PROVISIONAL ANCHORS']);
  assert.equal(classifyAdmission({stale:false,lookahead:false,circular:false,provisional:false}).admitted, true);
});

test('caption cue selection follows audio time and clamps end of chapter', () => {
  const cues=[{start:0,end:2},{start:2,end:4},{start:4,end:6}];
  assert.equal(cueAt(cues,0),0);
  assert.equal(cueAt(cues,2.3),1);
  assert.equal(cueAt(cues,999),2);
});

test('time formatting handles minute rollovers', () => {
  assert.equal(formatTime(64.3),'1:04');
  assert.equal(formatTime(0),'0:00');
});

test('chapter navigation wraps and has a stable direction',()=>{
  assert.equal(chapterDelta(0,-1,8),7);
  assert.equal(chapterDelta(7,1,8),0);
});
EOF
cd /mnt/data/gev_av_work && node --test mission.test.mjs 2>&1 | head -32

