export function brierScore(probability,outcome){
  if(outcome === null || outcome === undefined || outcome === 'unresolved') return null;
  const p=Number(probability), o=Number(outcome);
  if(!Number.isFinite(p)||p<0||p>1||![0,1].includes(o)) throw new RangeError('Probability must be in [0, 1] and outcome in {0, 1}.');
  return Math.round((p-o)**2*10000)/10000;
}
export function classifyAdmission({stale=false,lookahead=false,circular=false,provisional=false}={}){
  const reasons=[];
  if(stale) reasons.push('STALE SOURCE');
  if(lookahead) reasons.push('LOOK-AHEAD');
  if(circular) reasons.push('CIRCULAR SUPPORT');
  if(provisional) reasons.push('ONLY PROVISIONAL ANCHORS');
  return {admitted:reasons.length===0,reasons};
}
export function cueAt(cues,time){
  if(!cues?.length) return -1;
  const t=Number.isFinite(time)?time:0;
  for(let i=0;i<cues.length;i++){if(t>=cues[i].start && t<cues[i].end)return i;}
  return t<cues[0].start?0:cues.length-1;
}
export function formatTime(seconds){
  const s=Math.max(0,Math.floor(Number.isFinite(seconds)?seconds:0));
  return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
}
export function chapterDelta(index,direction,size){
  return ((index+direction)%size+size)%size;
}
EOF
