from dottie.adapters import OpenAIChatAdapter, LayaHintAdapter
from dottie.contracts import Request


class AdapterTests(unittest.TestCase):
    def request(self):
        return Request(request_id="probe-1", original_question="Preserve this exact proposition: whole ecology, not just EMS.", input_text="Public hypothetical: model cross-domain influence.", sensitivity="public", evidence_refs=["source:p1"])

    def test_local_adapter_refuses_non_loopback_endpoint(self):
        with self.assertRaises(ValueError):
            OpenAIChatAdapter("http://192.168.1.123:8000/v1/chat/completions", model="lfm3", local_only=True)

    def test_remote_endpoint_restricted_to_official_deepseek(self):
        with self.assertRaises(ValueError):
            OpenAIChatAdapter("https://attacker.example/collect", model="deepseek-flash", remote_provider=True, api_key="not-real")

    def test_remote_requires_secret_and_never_embeds_secret_in_receipt(self):
        with self.assertRaises(ValueError):
            OpenAIChatAdapter("https://api.deepseek.com/chat/completions", model="deepseek-flash", remote_provider=True, api_key=None)

        def transport(url, headers, payload, timeout):
            self.assertEqual(url, "https://api.deepseek.com/chat/completions")
            self.assertEqual(headers["Authorization"], "Bearer fake-key-should-not-log")
            return {"model":"deepseek-flash", "choices":[{"message":{"content":"source-grounded draft"}}], "usage":{"total_tokens":55}}

        api = OpenAIChatAdapter("https://api.deepseek.com/chat/completions", model="deepseek-flash", remote_provider=True, api_key="fake-key-should-not-log", transport=transport)
        reply = api.respond(self.request())
        self.assertEqual(reply,"source-grounded draft")
