"""Hypothesis map for coupled ecological effects, not a predictive world model.

This class can trace candidate dependencies given by a researcher. It does NOT
learn edges, establish causality, observe a city/world, or assign probability.
"""
from dataclasses import dataclass
from math import sqrt, isfinite


@dataclass(frozen=True)
class Node:
    node_id: str
    domain: str
    def __post_init__(self):
        if not self.node_id or not self.domain:
            raise ValueError("Node requires ID and domain")


@dataclass(frozen=True)
class Edge:
    origin: str
    target: str
    evidence_status: str
    source_ref: str
    def __post_init__(self):
        if not self.origin or not self.target or not self.source_ref:
            raise ValueError("Impact edges require origin, target, and exact source")
        if self.evidence_status not in ("HYPOTHETICAL", "OBSERVED", "EXPERIMENTAL"):
            raise ValueError("Invalid edge evidence class")


class DependencyGraph:
    def __init__(self):
        self.nodes = {}
        self.edges = []
    def add_node(self, node):
        if node.node_id in self.nodes:
            raise ValueError("Duplicate node ID")
        self.nodes[node.node_id] = node
    def add_edge(self, edge):
        if edge.origin not in self.nodes or edge.target not in self.nodes:
            raise ValueError("Both nodes must be explicitly registered")
        self.edges.append(edge)
    def trace_possible_paths(self, start, max_hops=3):
        if start not in self.nodes:
            raise ValueError("Unknown source node")
        if max_hops < 0 or max_hops > 6:
            raise ValueError("Unbounded world graph traversal prohibited")
        results = []
        stack = [(start, [start], [])]
        while stack:
            current, nodes, links = stack.pop()
            if links:
                states = {link.evidence_status for link in links}
                results.append({"target":current, "domain":self.nodes[current].domain,
                                "path":nodes,
                                "source_refs":[link.source_ref for link in links],
                                "evidence_status":next(iter(states)) if len(states)==1 else "MIXED",
                                "inference":"possible_dependency_path_not_a_forecast"})
            if len(links) < max_hops:
                for edge in self.edges:
                    if edge.origin == current and edge.target not in nodes:
                        stack.append((edge.target, nodes + [edge.target], links+[edge]))
        return results


def spectral_radius(matrix):
    """Exact spectral radius for 1x1 or 2x2 NONNEGATIVE influence matrix.

    Controlled test input only. K_u, K_c, and K_f must be estimated separately
    from experiment. No entries for real-world GMRI K matrices are known.
    Refuse larger matrices rather than supplying a silently inaccurate answer.
    """
    if not isinstance(matrix, list) or len(matrix) not in (1, 2) or any(not isinstance(row,list) or len(row)!=len(matrix) for row in matrix):
        raise ValueError("Prototype only supports square 1x1 or 2x2 influence matrices")
    for row in matrix:
        for value in row:
            if not isinstance(value,(float,int)) or isinstance(value,bool) or not isfinite(value) or value<0:
                raise ValueError("All influence estimates must be finite and nonnegative")
    if len(matrix)==1:
        return matrix[0][0]
    a,b=matrix[0];c,d=matrix[1]
    return (a+d+sqrt((a-d)**2+4*b*c))/2
