from dataclasses import dataclass
from datetime import datetime


def _date(s):
    d = datetime.fromisoformat(s)
    if d.tzinfo is None or d.utcoffset() is None:
        raise ValueError("Forecast timestamps must contain a timezone")
    return d


@dataclass(frozen=True)
class Forecast:
    forecast_id: str
    event_definition: str
    probability: float
    issued_at: str
    horizon_at: str
    source_refs: tuple[str, ...]

    def __post_init__(self):
        if not self.forecast_id or not self.event_definition or not self.source_refs:
            raise ValueError("A forecast requires event, ID and source lineage")
        brier_score(self.probability, None)
        if _date(self.horizon_at) <= _date(self.issued_at):
            raise ValueError("Horizon must follow forecast issue time")


def score_forecast(forecast, outcome, adjudicated_at):
    if outcome is None:
        return None
    if not adjudicated_at:
        raise ValueError("Scoring requires adjudication timestamp")
    if _date(adjudicated_at) < _date(forecast.horizon_at):
        raise ValueError("Cannot score before horizon")
    return brier_score(forecast.probability, outcome)
