"""Single-process, local-only experimental AEGIS identity and mission store.

No GrizOS or CopilotKit Intelligence dependency. Caller identity/approval values
are test-harness arguments, NOT real authentication. Do NOT expose this module
as a writable network API. No model inference or external action is performed.
"""
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
import json
import sqlite3
import uuid


@dataclass(frozen=True)
class AgentIdentity:
    agent_id: str
    display_name: str
    mandate: str
    memory_namespace: str
    lead: bool = False
    model_binding: str = 'unbound'
    worker_binding: str = 'unbound'


def official_roster():
    """Names requested by the principal; mandates are PROPOSED for review."""
    entries = (
        ('dottie', 'Dottie Hill', 'Independent watch officer; holds the watch, reviews evidence, challenges and briefs.', True),
        ('aegis-dugan', 'Dum Dum Dugan', 'Operational readiness, resilience, resource constraints, and recovery.', False),
        ('aegis-morita', 'Jim Morita', 'Primary-source retrieval, provenance, contradictory evidence, and reconciliation.', False),
        ('aegis-jones', 'Gabe Jones', 'Communications, engineering interfaces, infrastructure and technical dependency analysis.', False),
        ('aegis-dernier', 'Jacques Dernier', 'Cross-domain ecological pathways, consequences and geographic correlation.', False),
        ('aegis-falsworth', 'James Montgomery Falsworth', 'Independent QA/QI, adversarial checks, accountability and falsification.', False),
    )
    return tuple(AgentIdentity(k, n, m, f'private/{k}', lead) for k, n, m, lead in entries)


def validate_topology(proposed):
    if not isinstance(proposed, dict):
        raise TypeError('Topology must be a mapping')
    if proposed.get('variant') not in ('openduet-derived', 'standalone-local'):
        raise ValueError('Unqualified topology variant')
    for forbidden in ('requires_grizos', 'requires_copilotkit_intelligence', 'writes_live_gev'):
        if proposed.get(forbidden) is not False:
            raise ValueError(forbidden + ' must be False')
    if proposed.get('deployment_status') != 'design_only':
        raise ValueError('Design is not a deployment')
    expected = [a.agent_id for a in official_roster()]
    if len(proposed.get('agent_ids', [])) != len(expected) or set(proposed['agent_ids']) != set(expected):
        raise ValueError('Identity roster mismatch')
    if proposed.get('shares_model_server') is not True:
        raise ValueError('Common model service topology must be explicit')
    return {'agent_count':len(expected),'status':'DESIGN_ONLY','model_server_shared':True}


def _now():
    return datetime.now(timezone.utc).isoformat()


def _dumps(x):
    return json.dumps(x, ensure_ascii=False, sort_keys=True, separators=(',', ':'))


def _check_str(s, label):
    if not isinstance(s, str) or not s.strip() or len(s) > 20000:
        raise ValueError(f'{label} must be nonempty bounded text')
    return s


def _refs(refs):
    if not isinstance(refs, (tuple, list)) or not all(isinstance(x, str) and 0 < len(x) <= 500 for x in refs):
        raise TypeError('Evidence references must be a list of source IDs')
    return list(refs)


class AegisCommunity:
    def __init__(self, db_path):
        path = Path(db_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        self.db = sqlite3.connect(path, timeout=5)
        self.db.row_factory = sqlite3.Row
        self.db.execute('PRAGMA foreign_keys=ON')
        self.db.execute('PRAGMA busy_timeout=5000')
        self.db.executescript('''
            CREATE TABLE IF NOT EXISTS identities (agent_id TEXT PRIMARY KEY, name TEXT NOT NULL, mandate TEXT NOT NULL, memory_namespace TEXT UNIQUE NOT NULL, lead INTEGER NOT NULL);
            CREATE TABLE IF NOT EXISTS tasks (task_id TEXT PRIMARY KEY, sender TEXT NOT NULL, recipient TEXT NOT NULL, original_question TEXT NOT NULL, evidence_refs TEXT NOT NULL, status TEXT NOT NULL, execution_mode TEXT NOT NULL, created_at TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS members (task_id TEXT NOT NULL REFERENCES tasks(task_id), agent_id TEXT NOT NULL REFERENCES identities(agent_id), invitation TEXT NOT NULL, PRIMARY KEY(task_id,agent_id));
            CREATE TABLE IF NOT EXISTS messages (message_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), from_agent TEXT NOT NULL, to_agent TEXT NOT NULL, content TEXT NOT NULL, source_refs TEXT NOT NULL, created_at TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS findings (finding_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(task_id), actor_id TEXT NOT NULL, finding_text TEXT NOT NULL, source_refs TEXT NOT NULL, epistemic_status TEXT NOT NULL, live_gev_write INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
        ''')
        with self.db:
            for a in official_roster():
                self.db.execute('INSERT OR IGNORE INTO identities VALUES(?,?,?,?,?)', (a.agent_id, a.display_name, a.mandate, a.memory_namespace, int(a.lead)))

    def close(self):
        self.db.close()

    def _agent(self, agent_id):
        return self.db.execute('SELECT * FROM identities WHERE agent_id=?', (agent_id,)).fetchone()

    def get_task(self, task_id):
        row = self.db.execute('SELECT * FROM tasks WHERE task_id=?', (task_id,)).fetchone()
        if row is None:
            raise KeyError(task_id)
        return {**dict(row), 'evidence_refs':json.loads(row['evidence_refs'])}

    def _members(self, task_id):
        self.get_task(task_id)
        return {r[0] for r in self.db.execute('SELECT agent_id FROM members WHERE task_id=?', (task_id,))}

    def assign(self, *, task_id, sender, recipient, original_question, evidence_refs, operator_reviewed):
        if type(operator_reviewed) is not bool:
            raise TypeError('operator_reviewed must be a genuine Boolean, not text')
        if not operator_reviewed:
            raise PermissionError('Unreviewed mission cannot be assigned')
        if sender != 'dottie':
            raise PermissionError('Only the Dottie fixture assigns missions')
        if recipient == 'dottie' or not self._agent(recipient):
            raise ValueError('Must target a registered AEGIS identity')
        _check_str(task_id, 'task_id'); _check_str(original_question, 'original_question')
        refs = _refs(evidence_refs)
        normalized = {'task_id':task_id,'sender':sender,'recipient':recipient,'original_question':original_question,'evidence_refs':refs,'status':'queued','execution_mode':'simulation_only'}
        try:
            previous = self.get_task(task_id)
        except KeyError:
            previous = None
        if previous:
            if all(previous[k]==v for k,v in normalized.items()):
                return previous
            raise ValueError('Conflicting assignment with same task ID')
        with self.db:
            self.db.execute('INSERT INTO tasks VALUES(?,?,?,?,?,?,?,?)', (task_id,sender,recipient,original_question,_dumps(refs),'queued','simulation_only',_now()))
            for agent in (sender,recipient):
                self.db.execute('INSERT INTO members VALUES(?,?,?)', (task_id,agent,'initial_roster'))
        return self.get_task(task_id)

    def tasks_for(self, agent_id):
        if not self._agent(agent_id):
            raise ValueError('Unknown agent')
        return [self.get_task(r[0]) for r in self.db.execute('SELECT task_id FROM tasks WHERE recipient=? ORDER BY created_at', (agent_id,))]

    def invite(self, task_id, agent_id, *, approved_by):
        if approved_by != 'operator_fixture':
            raise PermissionError('Peer membership expansion requires operator fixture')
        if not self._agent(agent_id):
            raise ValueError('Unknown AEGIS agent')
        self.get_task(task_id)
        with self.db:
            self.db.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)', (task_id,agent_id,'operator_fixture'))
        return {'task_id':task_id,'agent_id':agent_id,'status':'EXPLICIT_INVITE_TEST_ONLY'}

    def message(self, task_id, from_agent, to_agent, content, *, source_refs=None, message_id=None):
        if from_agent not in self._members(task_id) or to_agent not in self._members(task_id):
            raise PermissionError('No mission membership for sender/recipient')
        _check_str(content,'content')
        refs = _refs(source_refs or [])
        if message_id is None:
            message_id = str(uuid.uuid4())
        _check_str(message_id,'message_id')
        existing = self.db.execute('SELECT * FROM messages WHERE message_id=?',(message_id,)).fetchone()
        if existing:
            record={**dict(existing),'source_refs':json.loads(existing['source_refs'])}
            if any((record[k]!=v) for k,v in {'task_id':task_id,'from_agent':from_agent,'to_agent':to_agent,'content':content,'source_refs':refs}.items()):
                raise ValueError('Conflicting message with same ID')
            return record
        with self.db:
            self.db.execute('INSERT INTO messages VALUES(?,?,?,?,?,?,?)',(message_id,task_id,from_agent,to_agent,content,_dumps(refs),_now()))
        return self.db_message(message_id)

    def db_message(self, message_id):
        row=self.db.execute('SELECT * FROM messages WHERE message_id=?',(message_id,)).fetchone()
        return {**dict(row),'source_refs':json.loads(row['source_refs'])}

    def messages(self, task_id, viewer):
        if viewer not in self._members(task_id):
            raise PermissionError('Non-member cannot read mission communication')
        return [self.db_message(r[0]) for r in self.db.execute('SELECT message_id FROM messages WHERE task_id=? ORDER BY rowid',(task_id,))]

    def report_finding(self, task_id, actor_id, finding_text, source_refs, *, finding_id, epistemic_status='MODEL_OUTPUT_UNVERIFIED'):
        task=self.get_task(task_id)
        if actor_id != task['recipient']:
            raise PermissionError('Only assigned worker intelligence can submit finding')
        if epistemic_status!='MODEL_OUTPUT_UNVERIFIED':
            raise ValueError('Inference is not a verified world event')
        _check_str(finding_id,'finding_id'); _check_str(finding_text,'finding_text')
        refs = _refs(source_refs)
        with self.db:
            if self.db.execute('SELECT 1 FROM findings WHERE finding_id=?',(finding_id,)).fetchone():
                raise ValueError('Duplicate finding ID')
            self.db.execute('INSERT INTO findings VALUES(?,?,?,?,?,?,?,?)',(finding_id,task_id,actor_id,finding_text,_dumps(refs),epistemic_status,0,_now()))
            self.db.execute('UPDATE tasks SET status=? WHERE task_id=?',('finding_submitted',task_id))
