"""AEGIS research fixture: durable local identities, missions, private notes, and audit.

This is intentionally *not* an authentication or execution service. Caller-supplied
agent IDs are laboratory test data and must never become network authorization.
No language model, GEV, browser or remote service is contacted.
"""
from dataclasses import asdict
from datetime import datetime, timezone
from hashlib import sha256
from pathlib import Path
import json
import sqlite3

from .aegis_community import official_roster

AEGIS_IDENTITIES = tuple(a for a in official_roster() if not a.lead)
AGENT_IDS = frozenset(a.agent_id for a in AEGIS_IDENTITIES)


def _json(data):
    return json.dumps(data, sort_keys=True, separators=(',', ':'), ensure_ascii=True)


def _check(value, label):
    if not isinstance(value, str) or not value.strip() or len(value) > 20000:
        raise ValueError(f'{label} requires bounded nonempty text')


def _refs(refs):
    if not isinstance(refs, (list, tuple)) or not all(isinstance(x, str) and x.strip() and len(x) <= 500 for x in refs):
        raise ValueError('Source references must be an explicit list of valid IDs')
    return list(refs)


class AegisOffice:
    """Fixture only. No proof of server-side identities, accounts or authority."""
    def __init__(self, path):
        p = Path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        self._db = sqlite3.connect(p, timeout=5)
        self._db.row_factory = sqlite3.Row
        self._db.execute('PRAGMA busy_timeout=5000')
        self._db.executescript('''
            CREATE TABLE IF NOT EXISTS identities (
                agent_id TEXT PRIMARY KEY, display_name TEXT NOT NULL,
                reports_to TEXT NOT NULL, memory_scope TEXT NOT NULL UNIQUE,
                mandate TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS missions (
                mission_id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES identities(agent_id),
                instruction TEXT NOT NULL, original_question TEXT NOT NULL,
                status TEXT NOT NULL, finding_text TEXT, source_refs TEXT,
                created_at TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS private_notes (
                agent_id TEXT NOT NULL REFERENCES identities(agent_id),
                note_id TEXT NOT NULL, note_text TEXT NOT NULL,
                provenance_ref TEXT NOT NULL, PRIMARY KEY(agent_id, note_id));
            CREATE TABLE IF NOT EXISTS events (
                seq INTEGER PRIMARY KEY AUTOINCREMENT, event_type TEXT NOT NULL,
                payload TEXT NOT NULL, prev_hash TEXT NOT NULL, hash TEXT NOT NULL);
        ''')
        with self._db:
            for a in AEGIS_IDENTITIES:
                self._db.execute('INSERT OR IGNORE INTO identities VALUES(?,?,?,?,?)',
                                 (a.agent_id, a.display_name, 'dottie', a.memory_namespace, a.mandate))

    def close(self):
        self._db.close()

    def _event(self, name, payload):
        previous = self._db.execute('SELECT hash FROM events ORDER BY seq DESC LIMIT 1').fetchone()
        prev_hash = previous['hash'] if previous else '0' * 64
        body = _json(payload)
        digest = sha256((prev_hash + '\n' + name + '\n' + body).encode('utf-8')).hexdigest()
        self._db.execute('INSERT INTO events(event_type,payload,prev_hash,hash) VALUES(?,?,?,?)',
                         (name, body, prev_hash, digest))

    def roster(self):
        return [dict(r) for r in self._db.execute('SELECT * FROM identities ORDER BY rowid')]

    def mission(self, mission_id):
        r = self._db.execute('SELECT * FROM missions WHERE mission_id=?', (mission_id,)).fetchone()
        if r is None:
            raise KeyError(mission_id)
        d = dict(r)
        d['source_refs'] = json.loads(d['source_refs']) if d['source_refs'] is not None else []
        return d

    def assign(self, mission_id, agent_id, instruction, *, original_question, actor_id='dottie'):
        if actor_id != 'dottie':
            raise PermissionError('Fixture assignment must originate with Dottie')
        if agent_id not in AGENT_IDS:
            raise ValueError('Not a registered independent AEGIS member')
        for key, val in [('mission_id', mission_id), ('instruction', instruction), ('original_question', original_question)]:
            _check(val, key)
        try:
            existing = self.mission(mission_id)
        except KeyError:
            existing = None
        if existing is not None:
            if (existing['agent_id'], existing['instruction'], existing['original_question']) == (agent_id, instruction, original_question):
                return existing
            raise ValueError('Mission idempotency conflict')
        with self._db:
            self._db.execute('INSERT INTO missions VALUES(?,?,?,?,?,?,?,?)',
                             (mission_id, agent_id, instruction, original_question, 'ASSIGNED', None, None,
                              datetime.now(timezone.utc).isoformat()))
            self._event('mission.assigned', {'mission_id':mission_id, 'agent_id':agent_id,
                                             'original_question':original_question, 'mode':'fixture_only'})
        return self.mission(mission_id)

    def submit_finding(self, mission_id, actor_id, finding_text, source_refs, *, claimed_status='ATTRIBUTED_UNVERIFIED'):
        mission = self.mission(mission_id)
        if mission['agent_id'] != actor_id:
            raise PermissionError('Only the assigned agent may file a finding')
        if claimed_status != 'ATTRIBUTED_UNVERIFIED':
            raise ValueError('Model or agent findings cannot certify themselves as verified')
        if mission['status'] != 'ASSIGNED':
            raise ValueError('Mission already closed or refused')
        _check(finding_text, 'finding_text')
        refs = _refs(source_refs)
        with self._db:
            self._db.execute('UPDATE missions SET status=?, finding_text=?, source_refs=? WHERE mission_id=?',
                             ('FINDING_SUBMITTED', finding_text, _json(refs), mission_id))
            self._event('finding.submitted', {'mission_id':mission_id, 'actor_id':actor_id,
                                              'finding_sha256':sha256(finding_text.encode()).hexdigest(),
                                              'source_refs':refs, 'finding_status':claimed_status})
        return self.mission(mission_id)

    def shared_findings(self, actor_id):
        if actor_id != 'dottie':
            raise PermissionError('Only Dottie reads the cross-mission report fixture')
        out = []
        for r in self._db.execute('SELECT * FROM missions WHERE status=? ORDER BY created_at', ('FINDING_SUBMITTED',)):
            d = self.mission(r['mission_id'])
            d.update({'actor_id':r['agent_id'], 'finding_status':'ATTRIBUTED_UNVERIFIED'})
            out.append(d)
        return out

    def refuse(self, mission_id, actor_id, *, reason):
        m = self.mission(mission_id)
        if m['agent_id'] != actor_id:
            raise PermissionError('Only assigned agent can refuse mission')
        if m['status'] != 'ASSIGNED':
            raise ValueError('Cannot refuse a closed mission')
        _check(reason, 'reason')
        with self._db:
            self._db.execute('UPDATE missions SET status=? WHERE mission_id=?', ('REFUSED', mission_id))
            self._event('mission.refused', {'mission_id':mission_id, 'agent_id':actor_id, 'reason':reason})
        return self.mission(mission_id)

    def store_private_note(self, agent_id, note_id, note_text, provenance_ref, *, actor_id):
        if agent_id not in AGENT_IDS:
            raise ValueError('Unregistered agent')
        if agent_id != actor_id:
            raise PermissionError('Only owning AEGIS identity may access its private fixture')
        for key,val in [('note_id',note_id),('note_text',note_text),('provenance_ref',provenance_ref)]:
            _check(val,key)
        with self._db:
            self._db.execute('INSERT INTO private_notes VALUES(?,?,?,?)',
                             (agent_id,note_id,note_text,provenance_ref))
            self._event('memory.note_added', {'agent_id':agent_id,'note_id':note_id,'provenance_ref':provenance_ref,
                                               'content_sha256':sha256(note_text.encode()).hexdigest()})

    def private_notes(self, agent_id, *, actor_id):
        if agent_id != actor_id:
            raise PermissionError('Private notes are not accessible to Dottie or another agent')
        if agent_id not in AGENT_IDS:
            raise ValueError('Not an AEGIS member')
        return [dict(r) for r in self._db.execute('SELECT * FROM private_notes WHERE agent_id=? ORDER BY rowid',(agent_id,))]

    def verify_events(self):
        previous = '0'*64
        count = 0
        for row in self._db.execute('SELECT * FROM events ORDER BY seq'):
            count+=1
            expected=sha256((previous + '\n' + row['event_type'] + '\n' + row['payload']).encode()).hexdigest()
            if row['prev_hash'] != previous or expected != row['hash']:
                return {'valid':False,'count':count,'first_invalid_seq':row['seq']}
            previous = row['hash']
        return {'valid':True,'count':count,'chain_head':previous,'independently_immutable':False}
