"""Read-only GEV MCP stdio *client* for bounded lab queries.

Only an explicitly configured local script or argv is started. Replies are
unreviewed source content, never canonical GEV world-state writes. The included
fixture is NOT the operational GEV. Do not expose this client to untrusted text.
"""
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlsplit
import json
import os
import select
import subprocess
import time


class GevMcpError(RuntimeError):
    pass


# GEV catalog names, not the app's mutating actions. Actual availability is
# further intersected with the server's advertised tools on every session.
READ_ONLY = frozenset({
    'get_earthquakes', 'get_active_fires', 'get_recent_launches',
    'aircraft_in_area', 'find_aircraft', 'get_aircraft_track', 'get_aircraft_info',
    'vessels_in_area', 'find_vessel', 'get_vessel_track',
    'satellites_overhead', 'next_satellite_pass', 'find_cctv_cameras',
    'get_cctv_snapshot', 'situation_brief', 'military_awareness',
    'get_tropical_cyclones', 'get_submarine_cables', 'get_datacenters',
})


class GevMcpReadClient:
    def __init__(self, *, mcp_script, command='node', api_base='http://127.0.0.1:4173', timeout=8):
        u = urlsplit(api_base)
        if (u.scheme != 'http' or u.hostname not in ('127.0.0.1','localhost') or
            u.username or u.password or u.path not in ('','/') or u.query or u.fragment or not u.port):
            raise ValueError('GEV must be reached through explicit local loopback transport')
        if not isinstance(timeout, (int,float)) or not 0 < timeout <= 60:
            raise ValueError('Timeout must be bounded')
        self.api_base = api_base.rstrip('/')
        self.timeout = timeout
        self.mcp_script = Path(mcp_script)
        if not self.mcp_script.is_file():
            raise FileNotFoundError(self.mcp_script)
        if isinstance(command, str):
            self.command=[command]
        elif isinstance(command, (list,tuple)) and command and all(isinstance(x,str) and x.strip() for x in command):
            self.command=list(command)
        else:
            raise ValueError('Explicit command executable required')
        self.proc=None
        self._buffer=b''
        self._seq=0
        self.tools=set()
        self.server_name='unreported'

    def __enter__(self):
        if self.proc is not None:
            raise GevMcpError('Session already active')
        # No shell and no network action from this client. For GEV Node users,
        # configure command (e.g. node) and mcp_script as a reviewed entrypoint.
        self.proc=subprocess.Popen(self.command+[str(self.mcp_script)],stdin=subprocess.PIPE,
                                   stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,bufsize=0)
        try:
            response=self._call('initialize',{'protocolVersion':'2025-03-26','capabilities':{},
                                               'clientInfo':{'name':'gmri-dottie-readonly-research','version':'0.3'}})
            if not isinstance(response,dict) or not isinstance(response.get('serverInfo'),dict):
                raise GevMcpError('Invalid MCP initialize response')
            self.server_name=response['serverInfo'].get('name','unreported')
            self._write({'jsonrpc':'2.0','method':'notifications/initialized'})
            tools=self._call('tools/list',{})
            if not isinstance(tools,dict) or not isinstance(tools.get('tools'),list):
                raise GevMcpError('Invalid tool catalog')
            self.tools={t['name'] for t in tools['tools'] if isinstance(t,dict) and isinstance(t.get('name'),str)}
            return self
        except Exception:
            self.close()
            raise

    def _write(self,payload):
        if self.proc is None or self.proc.poll() is not None:
            raise GevMcpError('MCP subprocess is not running')
        data=(json.dumps(payload,separators=(',',':'))+'\n').encode()
        if len(data)>256000:
            raise GevMcpError('MCP payload over size limit')
        try:
            self.proc.stdin.write(data)
            self.proc.stdin.flush()
        except (BrokenPipeError,OSError) as e:
            raise GevMcpError('Could not send MCP request') from e

    def _read(self,deadline):
        while time.monotonic() < deadline:
            if b'\n' in self._buffer:
                line,self._buffer=self._buffer.split(b'\n',1)
                if not line.strip():
                    continue
                try:
                    return json.loads(line)
                except (ValueError,UnicodeDecodeError) as e:
                    raise GevMcpError('Malformed MCP transport message') from e
            if self.proc.poll() is not None:
                raise GevMcpError('MCP server exited unexpectedly')
            ready,_,_=select.select([self.proc.stdout],[],[],max(0,min(.2,deadline-time.monotonic())))
            if ready:
                chunk=os.read(self.proc.stdout.fileno(),8192)
                if not chunk:
                    raise GevMcpError('MCP output ended')
                self._buffer+=chunk
                if len(self._buffer)>512000:
                    raise GevMcpError('MCP response exceeds size limit')
        raise GevMcpError('MCP request timed out')

    def _call(self,method,params):
        self._seq+=1
        ident=self._seq
        self._write({'jsonrpc':'2.0','id':ident,'method':method,'params':params})
        deadline=time.monotonic()+self.timeout
        while True:
            message=self._read(deadline)
            if not isinstance(message,dict) or message.get('id')!=ident:
                continue  # notifications and unrelated responses are not authoritative
            if 'error' in message:
                raise GevMcpError('MCP returned an error for '+method)
            if 'result' not in message:
                raise GevMcpError('MCP response lacks result')
            return message['result']

    def query(self,name,args):
        if self.proc is None:
            raise GevMcpError('Open a session before querying')
        if not isinstance(args,dict):
            raise TypeError('MCP tool arguments must be a mapping')
        if not isinstance(name,str) or name not in READ_ONLY:
            raise PermissionError('Tool outside read-only GEV catalog')
        if name not in self.tools:
            raise GevMcpError('Tool not advertised by connected GEV server')
        result=self._call('tools/call',{'name':name,'arguments':args})
        if not isinstance(result,dict) or result.get('isError'):
            raise GevMcpError('Read-only tool returned error')
        content=result.get('content')
        if not isinstance(content,list):
            raise GevMcpError('Invalid content from MCP tool')
        is_fixture='FIXTURE' in json.dumps(content) or 'FIXTURE' in self.server_name
        return {'tool':name,'status':'SOURCE_UNREVIEWED','fixture':is_fixture,
                'raw_content':content,'received_at':datetime.now(timezone.utc).isoformat(),
                'canonical_state':False,'live_gev_write':False,'observation_verified':False,
                'mcp_server_name':self.server_name}

    def close(self):
        proc=self.proc
        self.proc=None
        if proc is not None:
            try:
                proc.stdin.close()
            except OSError:
                pass
            if proc.poll() is None:
                proc.terminate()
                try:proc.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    proc.kill();proc.wait(timeout=1)
            else:
                proc.wait(timeout=1)

    def __exit__(self,*exc):
        self.close()
        return False
