"""Ollama Cloud research adapter and AEGIS worker/critic coordination.

Opt-in, PUBLIC data only. The flags are local operator test harness gates, not
strong authentication. No model output becomes evidence or an authorized action.
No connection to CopilotKit Intelligence, GrizOS, OpenRig or live GEV.
"""
from hashlib import sha256
import json
import os
import re
import urllib.error
import urllib.request

from .aegis import AegisOffice, AEGIS_IDENTITIES

OLLAMA_CHAT_URL = 'https://ollama.com/api/chat'
MAX_PROMPT_CHARS = 16000
MAX_REPLY_CHARS = 48000


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def _default_transport(*, url, headers, payload, timeout):
    """Use HTTPS with redirect refusal; never send API keys to another origin."""
    if url != OLLAMA_CHAT_URL:
        raise ValueError('Unpinned external inference destination')
    data=json.dumps(payload,ensure_ascii=False).encode('utf-8')
    request=urllib.request.Request(url, data=data, headers=headers, method='POST')
    opener=urllib.request.build_opener(_NoRedirect())
    try:
        with opener.open(request,timeout=timeout) as reply:
            if reply.status != 200:
                raise ConnectionError('Ollama returned non-success status')
            raw=reply.read(1_000_001)
    except (urllib.error.HTTPError,urllib.error.URLError,TimeoutError) as exc:
        # Do not relay provider error bodies, which can include sensitive input.
        raise ConnectionError('Ollama Cloud request failed; see network/provider logs') from exc
    if len(raw) > 1_000_000:
        raise ValueError('Provider response exceeded bounded size')
    try:
        return json.loads(raw)
    except (ValueError,UnicodeDecodeError) as exc:
        raise ValueError('Provider response is not valid JSON') from exc


def _validate_model(model):
    if not isinstance(model,str) or not re.fullmatch(r'[A-Za-z0-9._/:-]{2,120}',model):
        raise ValueError('Model identifier must be a literal Ollama catalog ID')
    return model


class OllamaCloudModel:
    """Single opt-in remote model binding; using a model never grants identity."""
    def __init__(self,model,*,api_key=None,transport=None,enable_remote=False,
                 endpoint=OLLAMA_CHAT_URL,timeout=25):
        if endpoint != OLLAMA_CHAT_URL:
            raise ValueError('Only the official Ollama Cloud endpoint is supported')
        if type(enable_remote) is not bool:
            raise TypeError('enable_remote must be a Boolean')
        if not isinstance(timeout,(int,float)) or not 0 < timeout <= 120:
            raise ValueError('Timeout must be bounded')
        self.model=_validate_model(model)
        self.api_key=api_key if api_key is not None else os.getenv('OLLAMA_API_KEY')
        self.transport=transport if transport is not None else _default_transport
        self.enable_remote=enable_remote
        self.timeout=timeout

    def generate(self,prompt,*,data_class,operator_export_reviewed,format_json=False):
        if type(operator_export_reviewed) is not bool:
            raise TypeError('Export review must be explicit Boolean; JSON strings do not authorize')
        if not self.enable_remote:
            raise PermissionError('Cloud inference disabled until separately opted in')
        if data_class != 'PUBLIC' or not operator_export_reviewed:
            raise PermissionError('Only explicitly reviewed PUBLIC inputs may reach cloud models')
        if not isinstance(self.api_key,str) or not self.api_key.strip():
            raise PermissionError('Ollama API key unavailable; no call made')
        if not isinstance(prompt,str) or not prompt.strip() or len(prompt)>MAX_PROMPT_CHARS:
            raise ValueError('Prompt must be nonempty bounded text')
        if type(format_json) is not bool:
            raise TypeError('format_json must be Boolean')
        payload={'model':self.model,'messages':[{'role':'user','content':prompt}],'stream':False}
        if format_json:
            payload['format']='json'
        response=self.transport(url=OLLAMA_CHAT_URL,
                                headers={'Authorization':'Bearer '+self.api_key,
                                         'Content-Type':'application/json'},
                                payload=payload,timeout=self.timeout)
        if not isinstance(response,dict) or not isinstance(response.get('message'),dict):
            raise ValueError('Invalid Ollama API response structure')
        text=response['message'].get('content')
        if not isinstance(text,str) or not text.strip() or len(text)>MAX_REPLY_CHARS:
            raise ValueError('Invalid or oversized text from Ollama API')
        out=text.strip()
        usage={}
        for k in ('prompt_eval_count','eval_count'):
            v=response.get(k)
            if isinstance(v,int) and not isinstance(v,bool) and 0<=v<=10_000_000:
                usage[k]=v
        receipt={'provider':'ollama_cloud','requested_model':self.model,
                 'reported_model':response.get('model') if isinstance(response.get('model'),str) else 'unreported',
                 'reported_model_pinned_checkpoint':False,
                 'input_sha256':sha256(prompt.encode()).hexdigest(),
                 'output_sha256':sha256(out.encode()).hexdigest(),
                 'tokens':usage,'model_output_is_verified_evidence':False,
                 'real_cloud_call_performed':self.transport is _default_transport}
        return {'text':out,'receipt':receipt}


def _critic_report(raw):
    try:
        report=json.loads(raw)
    except (ValueError,TypeError) as exc:
        raise ValueError('Critic did not return structured JSON') from exc
    if not isinstance(report,dict) or set(report) != {'issues','disposition'}:
        raise ValueError('Critic report shape invalid')
    if report['disposition'] not in ('NEEDS_VERIFICATION','NO_ACTIONABLE_FINDINGS','INCOMPLETE'):
        raise ValueError('Critic may not self-certify verification')
    if not isinstance(report['issues'],list) or len(report['issues']) > 25:
        raise ValueError('Critic issue list is not bounded')
    allowed={'test','file','code_claim','doc_note'}
    for issue in report['issues']:
        if (not isinstance(issue,dict) or not {'kind','target','claim','evidence_ref'}<=set(issue)
            or issue['kind'] not in allowed
            or not all(isinstance(issue[k],str) and issue[k].strip() and len(issue[k]) <= 1600
                       for k in ('target','claim','evidence_ref'))):
            raise ValueError('Criticism must become an identified test, file, code claim, or doc note')
    return report


class OllamaAegisCoordinator:
    """Dottie fixture assigns one AEGIS worker; critic can only recommend review.

    Run triggers external network traffic only when both model adapters are
    explicitly enabled and operator has reviewed this mission's entire PUBLIC
    input. This is not a production permission service.
    """
    def __init__(self,office,*,worker,critic):
        if not isinstance(office,AegisOffice):
            raise TypeError('AEGIS mission store required')
        if not isinstance(worker,OllamaCloudModel) or not isinstance(critic,OllamaCloudModel):
            raise TypeError('Explicit Ollama worker and critic bindings required')
        if worker.model==critic.model:
            raise ValueError('Reviewer must use a distinct model ID')
        self.office=office
        self.worker=worker
        self.critic=critic

    def run_public_mission(self,mission_id,*,operator_export_reviewed,source_refs,data_class='PUBLIC'):
        # Check everything feasible before calling the remote service.
        if type(operator_export_reviewed) is not bool:
            raise TypeError('Operator approval must be Boolean')
        if not operator_export_reviewed or data_class!='PUBLIC':
            raise PermissionError('No remote calls without review of PUBLIC brief')
        if not isinstance(source_refs,(list,tuple)) or not all(isinstance(x,str) and x.strip() and len(x)<=500 for x in source_refs):
            raise ValueError('Explicit provenance refs required')
        mission=self.office.mission(mission_id)
        if mission['status']!='ASSIGNED':
            raise ValueError('Mission is not awaiting a worker; repeated calls may bill twice')
        identity=next(x for x in AEGIS_IDENTITIES if x.agent_id==mission['agent_id'])
        prompt=('You are the assigned AEGIS researcher for this bounded mission. '
                'The role is a durable identity separate from the language model. '
                'Do not execute tools or assume source claims are verified. '
                'Preserve the exact original question, identify uncertainty and cite provided source IDs.\n'
                f'AEGIS AGENT: {identity.display_name} ({identity.agent_id})\n'
                f'MANDATE: {identity.mandate}\n'
                f'ORIGINAL QUESTION (verbatim): {mission["original_question"]}\n'
                f'ASSIGNED WORK: {mission["instruction"]}\n'
                f'REFERENCE IDS (not source content): {json.dumps(source_refs)}\n'
                'Output a concise evidence-conscious draft, not a world-state observation.')
        try:
            worker_reply=self.worker.generate(prompt,data_class='PUBLIC',
                                               operator_export_reviewed=operator_export_reviewed)
        except (ConnectionError,TimeoutError,ValueError,PermissionError,OSError) as exc:
            return {'mission_id':mission_id,'worker_id':identity.agent_id,'status':'WORKER_FAILED',
                    'error_type':type(exc).__name__,'finding_status':None,
                    'autonomous_changes_authorized':False,'real_gev_write':False}
        # Persist only attributed and UNVERIFIED work, never a VERIFIED assertion.
        self.office.submit_finding(mission_id,identity.agent_id,worker_reply['text'],source_refs)
        critic_prompt=('You are an independent model critic. Your judgment is advisory. '
                       'Do not execute tools or claim source verification. '
                       'Return STRICT JSON only with exactly two keys: '
                       '"issues" (array of {"kind":"test|file|code_claim|doc_note",'
                       '"target":string,"claim":string,"evidence_ref":string}) and '
                       '"disposition" (NEEDS_VERIFICATION|NO_ACTIONABLE_FINDINGS|INCOMPLETE). '
                       'Convert each objection to a reproducible test, identified file, exact code claim '
                       'or documentation note. Never mark an artifact verified or approved.\n'
                       f'ORIGINAL QUESTION: {mission["original_question"]}\n'
                       f'WORKER IDENTIFIER: {identity.agent_id}\n'
                       f'WORKER OUTPUT (unverified): {worker_reply["text"]}\n'
                       f'EXTERNAL SOURCE IDS: {json.dumps(source_refs)}')
        result={'mission_id':mission_id,'worker_id':identity.agent_id,'status':'REVIEW_REQUIRED',
                'original_question':mission['original_question'],
                'finding_status':'ATTRIBUTED_UNVERIFIED',
                'worker_receipt':worker_reply['receipt'],
                'critic':None,'critic_receipt':None,
                'autonomous_changes_authorized':False,'real_gev_write':False,
                'operator_adjudication_required':True}
        try:
            reply=self.critic.generate(critic_prompt,data_class='PUBLIC',
                                       operator_export_reviewed=operator_export_reviewed,format_json=True)
            result['critic']=_critic_report(reply['text'])
            result['critic_receipt']=reply['receipt']
        except (ConnectionError,TimeoutError,OSError,ValueError,PermissionError,TypeError) as exc:
            result['status']='CRITIC_UNRELIABLE' if isinstance(exc,(ValueError,TypeError)) else 'CRITIC_UNAVAILABLE'
            result['critic_error_type']=type(exc).__name__
        return result
