"""Experimental learning: detect unknowns, persist reviewed corrections, score outcomes.

NOT model training. NOT a trusted credential store or authenticated approval service.
Caller-provided 'human:' IDs are test fixtures, not cryptographic identities.
A model's proposed correction NEVER becomes active without independent review.
"""
from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
from hashlib import sha256
from pathlib import Path
import json
import sqlite3


class LearningState(str, Enum):
    PENDING_REVIEW = 'PENDING_REVIEW'
    APPROVED_FOR_RETRIEVAL = 'APPROVED_FOR_RETRIEVAL'
    REJECTED = 'REJECTED'
    SUPERSEDED = 'SUPERSEDED'


@dataclass(frozen=True)
class UnknownAssessment:
    unknown_kind: str
    next_action: str
    evidence_verified: bool = False
    reason: str = ''


def _required_string(value, field, max_chars=16000):
    if type(value) is not str or not value.strip() or len(value) > max_chars:
        raise ValueError(f'{field} must be bounded non-empty text')
    return value


def _source_refs(value):
    if type(value) not in (tuple, list) or not value or not all(type(x) is str and x.strip() and len(x) < 700 for x in value):
        raise ValueError('At least one explicit bounded evidence source ID is required')
    return list(value)


def assess_unknown(sources):
    """Deterministic information-gap triage, never an inference quality verdict.

    Inputs are SOURCE METADATA from an authorized ingestion layer, not model claims.
    This classifier does not browse the internet and cannot establish facts.
    """
    if type(sources) not in (list, tuple):
        raise TypeError('Sources must be an explicit list or tuple')
    for s in sources:
        if type(s) is not dict or s.get('kind') not in {'model_output','primary','secondary','user_report'}:
            raise ValueError('Unrecognized source metadata')
        _required_string(s.get('source_ref'), 'source_ref', 700)
        _required_string(s.get('claim'), 'claim', 12000)
        if type(s.get('fresh')) is not bool:
            raise TypeError('fresh must be explicit Boolean from ingestion')
    if not sources:
        return UnknownAssessment('MISSING_EVIDENCE','SEARCH_OR_REQUEST',reason='No source records supplied')
    candidates=[s for s in sources if s['kind']!='model_output']
    if not candidates:
        return UnknownAssessment('MODEL_ONLY','SEARCH_OR_REQUEST',reason='Model output is not independent evidence')
    fresh=[s for s in candidates if s['fresh']]
    if not fresh:
        return UnknownAssessment('STALE_SOURCE','REFRESH_SOURCE',reason='No current sources')
    independent=[s for s in fresh if s['kind'] in ('primary','secondary')]
    if len({s['claim'] for s in independent})>1:
        return UnknownAssessment('CONFLICTING_SOURCES','ADJUDICATE',reason='Independent source claims differ')
    if not independent:
        return UnknownAssessment('UNVERIFIED_REPORT','CORROBORATE',reason='Only unverified reports and model output')
    return UnknownAssessment('SOURCE_NEEDS_REVIEW','CHECK_PROVENANCE',reason='Sources are present, but have not been independently adjudicated')


def _json(x):
    return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False)


def _question_key(q):
    return sha256(q.encode('utf-8')).hexdigest()


def _utc():
    return datetime.now(timezone.utc).isoformat()


class LearningJournal:
    """Single-writer durable learning fixture; does not authenticate users or protect host compromise."""

    def __init__(self, path):
        p=Path(path)
        p.parent.mkdir(parents=True,exist_ok=True)
        self.db=sqlite3.connect(p,timeout=6)
        self.db.row_factory=sqlite3.Row
        self.db.execute('PRAGMA journal_mode=WAL')
        self.db.execute('PRAGMA synchronous=FULL')
        self.db.execute('PRAGMA busy_timeout=6000')
        self.db.executescript('''
            CREATE TABLE IF NOT EXISTS corrections (
              correction_id TEXT PRIMARY KEY, scope TEXT NOT NULL, question_key TEXT NOT NULL,
              original_question TEXT NOT NULL, proposed_correction TEXT NOT NULL,
              proposer_id TEXT NOT NULL, source_refs TEXT NOT NULL,
              status TEXT NOT NULL, reviewer_id TEXT, independent_check_ref TEXT,
              reviewer_notes TEXT, created_at TEXT NOT NULL, reviewed_at TEXT);
            CREATE INDEX IF NOT EXISTS correction_lookup ON corrections(scope,question_key,status);
            CREATE TABLE IF NOT EXISTS forecasts (
              forecast_id TEXT PRIMARY KEY, scope TEXT NOT NULL, question TEXT NOT NULL,
              probability REAL NOT NULL, outcome_deadline TEXT NOT NULL,
              evidence_refs TEXT NOT NULL, status TEXT NOT NULL, actual_yes INTEGER,
              outcome_ref TEXT, reviewer_id TEXT, brier_score REAL);
            CREATE TABLE IF NOT EXISTS learning_events (
              event_seq INTEGER PRIMARY KEY AUTOINCREMENT, event_type TEXT NOT NULL,
              payload TEXT NOT NULL, previous_hash TEXT NOT NULL, entry_hash TEXT NOT NULL);
        ''')

    def close(self):
        self.db.close()

    def _event(self, name, data):
        previous=self.db.execute('SELECT entry_hash FROM learning_events ORDER BY event_seq DESC LIMIT 1').fetchone()
        previous=previous['entry_hash'] if previous is not None else '0'*64
        payload=_json(data)
        digest=sha256((previous+'\n'+name+'\n'+payload).encode()).hexdigest()
        self.db.execute('INSERT INTO learning_events(event_type,payload,previous_hash,entry_hash) VALUES(?,?,?,?)',
                        (name,payload,previous,digest))

    def event_count(self):
        return self.db.execute('SELECT count(*) FROM learning_events').fetchone()[0]

    def verify_journal(self):
        previous='0'*64
        for row in self.db.execute('SELECT * FROM learning_events ORDER BY event_seq'):
            digest=sha256((previous+'\n'+row['event_type']+'\n'+row['payload']).encode()).hexdigest()
            if row['previous_hash']!=previous or row['entry_hash']!=digest:
                return {'valid':False,'first_invalid_event':row['event_seq']}
            previous=row['entry_hash']
        return {'valid':True,'event_count':self.event_count(), 'chain_head':previous,
                'independently_immutable':False}

    def _correction(self, correction_id):
        row=self.db.execute('SELECT * FROM corrections WHERE correction_id=?',(correction_id,)).fetchone()
        if row is None:
            raise KeyError(correction_id)
        d=dict(row); d['source_refs']=json.loads(d['source_refs'])
        return d

    def propose(self, correction_id, *, scope, original_question, proposed_correction, proposer_id, source_refs):
        for key,value in (('correction_id',correction_id),('scope',scope),('original_question',original_question),
                          ('proposed_correction',proposed_correction),('proposer_id',proposer_id)):
            _required_string(value,key)
        refs=_source_refs(source_refs)
        if len(correction_id)>200 or len(scope)>200:
            raise ValueError('ID or scope is too long')
        # Prevent namespace collisions and cross-agent memory contamination.
        if not (scope.startswith('dottie/') or scope.startswith('aegis/')):
            raise ValueError('Unknown research memory scope')
        with self.db:
            self.db.execute('''INSERT INTO corrections (
              correction_id,scope,question_key,original_question,proposed_correction,
              proposer_id,source_refs,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)''',
              (correction_id,scope,_question_key(original_question),original_question,proposed_correction,
               proposer_id,_json(refs),LearningState.PENDING_REVIEW.value,_utc()))
            self._event('correction.proposed',{'correction_id':correction_id,'scope':scope,
                        'question_sha256':_question_key(original_question),
                        'correction_sha256':sha256(proposed_correction.encode()).hexdigest(),
                        'status':LearningState.PENDING_REVIEW.value})
        return self._correction(correction_id)

    def adjudicate(self, correction_id, *, reviewer_id, approve, independent_check_ref, reviewer_notes):
        if type(approve) is not bool:
            raise TypeError('Review approval must be a literal Boolean')
        for k,v in (('reviewer_id',reviewer_id),('independent_check_ref',independent_check_ref),('reviewer_notes',reviewer_notes)):
            _required_string(v,k)
        row=self._correction(correction_id)
        if row['status']!=LearningState.PENDING_REVIEW.value:
            raise ValueError('Already reviewed; do not silently revise')
        # These role labels are NOT authentication. Production requires real separate sign-in.
        if not reviewer_id.startswith('human:') or reviewer_id==row['proposer_id']:
            raise PermissionError('A model or proposing worker cannot approve its own correction')
        if approve and self.db.execute('''SELECT 1 FROM corrections WHERE scope=? AND question_key=?
                                      AND status=?''',(row['scope'],row['question_key'],LearningState.APPROVED_FOR_RETRIEVAL.value)).fetchone():
            raise ValueError('Conflicting active correction: independent reconciliation required')
        status=LearningState.APPROVED_FOR_RETRIEVAL if approve else LearningState.REJECTED
        with self.db:
            self.db.execute('''UPDATE corrections SET status=?,reviewer_id=?,independent_check_ref=?,
                            reviewer_notes=?,reviewed_at=? WHERE correction_id=? AND status=?''',
                            (status.value,reviewer_id,independent_check_ref,reviewer_notes,_utc(),correction_id,
                             LearningState.PENDING_REVIEW.value))
            self._event('correction.reviewed',{'correction_id':correction_id,'reviewer_id':reviewer_id,
                        'status':status.value,'independent_check_ref':independent_check_ref})
        return self._correction(correction_id)

    def recall(self, original_question, *, scope):
        _required_string(original_question,'original_question')
        _required_string(scope,'scope')
        rows=self.db.execute('''SELECT correction_id FROM corrections WHERE scope=? AND question_key=?
                AND status=?''',(scope,_question_key(original_question),LearningState.APPROVED_FOR_RETRIEVAL.value)).fetchall()
        if len(rows)>1:
            raise RuntimeError('Duplicate active corrections: escalate instead of choosing')
        return self._correction(rows[0]['correction_id']) if rows else None

    def training_candidates(self, *, scope):
        """List only INTERNAL human-reviewed examples; export and training are NOT approved."""
        _required_string(scope,'scope')
        rows=self.db.execute('''SELECT correction_id FROM corrections WHERE scope=? AND status=? ORDER BY created_at''',
                (scope,LearningState.APPROVED_FOR_RETRIEVAL.value))
        return [{**self._correction(r['correction_id']),
                 'learning_state':'HUMAN_REVIEWED_EXAMPLE_ONLY',
                 'model_weights_updated':False,
                 'training_export_authorized':False,
                 'privacy_review_required':True} for r in rows]

    def add_forecast(self, forecast_id, *, scope, question, probability, outcome_deadline, evidence_refs):
        for k,v in (('forecast_id',forecast_id),('scope',scope),('question',question),
                    ('outcome_deadline',outcome_deadline)):
            _required_string(v,k)
        _source_refs(evidence_refs)
        if type(probability) not in (float,int) or not 0<=probability<=1:
            raise ValueError('Probability must be numeric 0..1')
        # Require an offset-aware ISO8601 outcome deadline, not a free-form date.
        parsed=datetime.fromisoformat(outcome_deadline)
        if parsed.tzinfo is None or parsed.utcoffset() is None:
            raise ValueError('Outcome deadline requires timezone')
        with self.db:
            self.db.execute('''INSERT INTO forecasts(forecast_id,scope,question,probability,outcome_deadline,
                             evidence_refs,status) VALUES(?,?,?,?,?,?,?)''',
                            (forecast_id,scope,question,float(probability),outcome_deadline,_json(_source_refs(evidence_refs)),'PENDING'))
            self._event('forecast.registered',{'forecast_id':forecast_id,'scope':scope,
                         'question_sha256':_question_key(question),'probability':float(probability)})
        return {'forecast_id':forecast_id,'status':'PENDING','scored':False}

    def score_forecast(self, forecast_id, *, actual_yes, outcome_ref, reviewer_id):
        if type(actual_yes) is not bool:
            raise TypeError('Outcome must be a literal Boolean')
        _required_string(reviewer_id,'reviewer_id');_required_string(outcome_ref,'outcome_ref')
        if not reviewer_id.startswith('human:'):
            raise PermissionError('Outcome cannot self-adjudicate via model')
        row=self.db.execute('SELECT * FROM forecasts WHERE forecast_id=?',(forecast_id,)).fetchone()
        if row is None:
            raise KeyError(forecast_id)
        if row['status']!='PENDING':
            raise ValueError('Outcome already adjudicated')
        if datetime.now(timezone.utc)<datetime.fromisoformat(row['outcome_deadline']):
            raise ValueError('Outcome deadline not reached')
        score=(row['probability']-float(actual_yes))**2
        with self.db:
            self.db.execute('''UPDATE forecasts SET status=?,actual_yes=?,outcome_ref=?,reviewer_id=?,
                            brier_score=? WHERE forecast_id=?''',
                            ('SCORED',int(actual_yes),outcome_ref,reviewer_id,score,forecast_id))
            self._event('forecast.scored',{'forecast_id':forecast_id,'outcome_ref':outcome_ref,
                         'reviewer_id':reviewer_id,'score':score})
        return {'forecast_id':forecast_id,'status':'SCORED','brier_score':score,
                'outcome_source':outcome_ref,'model_quality_verified':False}

    def forecast_metrics(self, *, scope):
        _required_string(scope,'scope')
        a=self.db.execute('''SELECT count(*) as n,avg(brier_score) as b FROM forecasts
                            WHERE scope=? AND status='SCORED' ''',(scope,)).fetchone()
        p=self.db.execute("SELECT count(*) FROM forecasts WHERE scope=? AND status='PENDING'",(scope,)).fetchone()[0]
        return {'scored':a['n'],'pending':p,'mean_brier_score':a['b'],
                'forecast_calibration_verified':False,'outcome_review_is_fixture_only':True}
